      ctx.fillStyle = '#8a6a1f';
      ctx.beginPath();
      ctx.ellipse(item.x, item.y + 8, 16, 6, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#ffd94a';
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
